const THEMES = {
    home: FLOATERS,
    couchcast: COUCHCAST_FLOATERS,
    halloween: HALLOWEEN_FLOATERS,
    holiday: HOLIDAY_FLOATERS,
    circus: CIRCUS_FLOATERS,
    trivia: TRIVIA_FLOATERS,
    animals: ANIMALS_FLOATERS,
    lists: LISTS_FLOATERS,
    jeffinitely: [],   // 📼 draws its own full-colour retro scene instead (RetroBackdrop.jsx)
};

export default function AnimatedBackground() {
    const { theme, cover } = useBackgroundTheme();
    const floaters = THEMES[theme] || THEMES.home;

    return (
        <div className={`gt-bg theme-${theme} ${cover ? 'gt-bg-cover' : ''}`} aria-hidden="true">
            <div className="gt-blob b1" />
            <div className="gt-blob b2" />
            <div className="gt-blob b3" />
            {theme === 'jeffinitely' && <RetroBackdrop />}

            {floaters.map((f, i) => (
                <div
                    key={i}
                    className="gt-floater"
                    style={{
                        top: f.top,
                        left: f.left,
                        width: f.size,
                        height: f.size,
                        '--dur': `${f.dur}s`,
                        '--delay': `${f.delay}s`,
                        '--rot': `${f.rot}deg`,
                    }}
                >
                    <svg viewBox="0 0 100 100" className="gt-floater-svg">
                        {ICONS[f.icon]}
                    </svg>
                </div>
            ))}

            <div className="gt-vignette" />
        </div>
    );
}
